def t(key, **kw):
    v = S[key]; i = 0 if LANG["v"] == "en" else 1
    if isinstance(v, dict): return {k: x[i] for k, x in v.items()}
    s = v[i]
    return s.format(**kw) if kw and isinstance(s, str) else s
